class Countdown:
    def __init__(self, start):
        self.current = start

    def __iter__(self):
        return self

    def __next__(self):
        if self.current <= 0:
            raise StopIteration
        value = self.current
        self.current -= 1
        return value


for n in Countdown(3):
    print(n, end=" ")
print("Lift off!")
print(list(Countdown(5)))

from itertools import islice


def read_lines(path):
    with open(path, encoding="utf-8") as f:
        for line in f:
            yield line.rstrip("\n")


def only(level, lines):
    for line in lines:
        if f" {level} " in line:
            yield line


def messages(lines):
    for line in lines:
        yield line.split(" ", 3)[3]


errors = messages(only("ERROR", read_lines("app.log")))
print(type(errors).__name__)
for msg in islice(errors, 2):
    print("-", msg)

